import type { Request, Response } from 'express';

export type Product = {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  image: string;
  description: string;
  featured: boolean;
};

const products: Product[] = [
  {
    id: 'speckled-ceramic-mug',
    name: 'Speckled Ceramic Mug',
    category: 'pottery',
    price: 28,
    image: 'https://picsum.photos/seed/speckled-ceramic-mug/600/600',
    description:
      'Hand-thrown stoneware mug with a warm speckled glaze. Each piece is unique, fired in a wood kiln for a one-of-a-kind finish.',
    featured: true,
  },
  {
    id: 'terracotta-planter',
    name: 'Terracotta Planter',
    category: 'pottery',
    price: 45,
    image: 'https://picsum.photos/seed/terracotta-planter/600/600',
    description:
      'Handcrafted terracotta planter with a drainage hole and saucer. Perfect for herbs, succulents, or small houseplants.',
    featured: false,
  },
  {
    id: 'stoneware-bowl-set',
    name: 'Stoneware Bowl Set',
    category: 'pottery',
    price: 65,
    image: 'https://picsum.photos/seed/stoneware-bowl-set/600/600',
    description:
      'A set of three nesting stoneware bowls in complementary earth tones. Dishwasher safe and food grade.',
    featured: false,
  },
  {
    id: 'handwoven-throw-blanket',
    name: 'Hand-woven Throw Blanket',
    category: 'textiles',
    price: 89,
    image: 'https://picsum.photos/seed/handwoven-throw-blanket/600/600',
    description:
      'Luxuriously soft throw blanket woven from 100% organic cotton. Features a classic herringbone pattern in warm natural tones.',
    featured: true,
  },
  {
    id: 'linen-table-runner',
    name: 'Linen Table Runner',
    category: 'textiles',
    price: 38,
    image: 'https://picsum.photos/seed/linen-table-runner/600/600',
    description:
      'Stonewashed linen table runner with hand-stitched edges. Adds effortless elegance to any dining table.',
    featured: false,
  },
  {
    id: 'macrame-wall-hanging',
    name: 'Macramé Wall Hanging',
    category: 'textiles',
    price: 72,
    image: 'https://picsum.photos/seed/macrame-wall-hanging/600/600',
    description:
      'Intricate macramé wall hanging knotted from natural cotton rope. Mounted on a driftwood branch for a bohemian touch.',
    featured: false,
  },
  {
    id: 'walnut-serving-board',
    name: 'Walnut Serving Board',
    category: 'woodwork',
    price: 55,
    image: 'https://picsum.photos/seed/walnut-serving-board/600/600',
    description:
      'Hand-planed American black walnut serving board with a food-safe oil finish. Beautiful grain patterns make each board unique.',
    featured: true,
  },
  {
    id: 'oak-candle-holder',
    name: 'Oak Candle Holder',
    category: 'woodwork',
    price: 32,
    image: 'https://picsum.photos/seed/oak-candle-holder/600/600',
    description:
      'Turned white oak candle holder with a smooth satin finish. Fits standard taper candles and pillar candles.',
    featured: false,
  },
  {
    id: 'carved-wooden-spoon-set',
    name: 'Carved Wooden Spoon Set',
    category: 'woodwork',
    price: 24,
    image: 'https://picsum.photos/seed/carved-wooden-spoon-set/600/600',
    description:
      'Set of three hand-carved cherry wood spoons in varying sizes. Sanded smooth and finished with beeswax.',
    featured: false,
  },
  {
    id: 'hammered-silver-ring',
