    description:
      'Hand-rolled ceramic beads in earthy tones strung on a waxed linen cord. A wearable piece of art.',
    featured: false,
  },
  {
    id: 'copper-leaf-earrings',
    name: 'Copper Leaf Earrings',
    category: 'jewelry',
    price: 35,
    image: 'https://picsum.photos/seed/copper-leaf-earrings/600/600',
    description:
      'Delicate copper earrings shaped like leaves, with a patinated finish. Lightweight and hypoallergenic ear wires.',
    featured: false,
  },
];

export default function handler(req: Request, res: Response) {
  const { category, featured } = req.query;

  let result = [...products];

  if (category && typeof category === 'string') {
    result = result.filter((p) => p.category === category);
  }

  if (featured === 'true') {
    result = result.filter((p) => p.featured);
  }

  res.json(result);
}

import { useState, useEffect } from 'react';
import { Link, NavLink } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { cn } from '@/lib/utils';

const navLinks = [
  { label: 'Home', to: '/' },
  { label: 'Shop', to: '/products' },
  { label: 'About', to: '/about' },
];

export default function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header
      className={cn(
        'fixed top-0 left-0 right-0 z-50 transition-all duration-300',
        scrolled
          ? 'bg-[#FAF7F2] shadow-sm border-b border-[#DDD5C8]'
          : 'bg-[#FAF7F2]/95 backdrop-blur-sm'
      )}
    >
      <div className="max-w-7xl mx-auto px-6 lg:px-8">
        <div className="flex items-center justify-between h-20">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Artisan Goods Co."
              className="h-10 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map(({ label, to }) => (
              <NavLink
                key={to}
                to={to}
                end={to === '/'}
                className={({ isActive }) =>
                  cn(
                    'relative text-sm font-medium tracking-wide transition-colors duration-200',
                    'text-[#5C3D2E] hover:text-[#C4622D]',
                    'after:absolute after:bottom-[-3px] after:left-0 after:h-[2px] after:bg-[#C4622D]',
                    'after:transition-all after:duration-300',
                    isActive ? 'after:w-full text-[#C4622D]' : 'after:w-0 hover:after:w-full'
                  )
                }
              >
                {label}
              </NavLink>
            ))}
          </nav>

          {/* Desktop CTA */}
          <div className="hidden md:flex items-center">
            <Link
              to="/products"
              className="px-5 py-2.5 bg-[#C4622D] text-white text-sm font-medium rounded-full hover:bg-[#a8521f] transition-colors duration-200"
            >
              Shop Now
            </Link>
          </div>

          {/* Mobile Menu Toggle */}
          <button
            className="md:hidden p-2 text-[#5C3D2E] hover:text-[#C4622D] transition-colors"
            onClick={() => setMobileOpen((o) => !o)}
            aria-label={mobileOpen ? 'Close menu' : 'Open menu'}
          >
            {mobileOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <div
        className={cn(
          'md:hidden overflow-hidden transition-all duration-300 bg-[#FAF7F2] border-t border-[#DDD5C8]',
          mobileOpen ? 'max-h-72 opacity-100' : 'max-h-0 opacity-0'
        )}
      >
        <nav className="flex flex-col px-6 py-4 gap-4">
          {navLinks.map(({ label, to }) => (
            <NavLink
              key={to}
              to={to}
              end={to === '/'}
