import { RouteObject } from 'react-router-dom';
import { lazy } from 'react';
import HomePage from './pages/index';
import ProductsPage from './pages/products';
import AboutPage from './pages/about';
import type { Product } from './server/api/products/GET';

// Eager import so renderToString doesn't hit a Suspense boundary on 404 routes
// and abort to client rendering. The prod 404 page is tiny; the dev-tools
// variant stays lazy because it pulls in dev-only code we don't want in
// production bundles.
import ProdNotFoundPage from './pages/_404';

const NotFoundPage = import.meta.env.DEV
  ? lazy(() => import('../dev-tools/src/PageNotFound'))
  : ProdNotFoundPage;

async function fetchProducts(params?: string): Promise<Product[]> {
  const base = typeof window !== 'undefined' ? '' : 'http://localhost:3000';
  const url = `${base}/api/products${params ? `?${params}` : ''}`;
  const res = await fetch(url);
  if (!res.ok) throw new Response(null, { status: res.status });
  return res.json() as Promise<Product[]>;
}

export const routes: RouteObject[] = [
  {
    path: '/',
    element: <HomePage />,
    loader: async () => {
      const featured = await fetchProducts('featured=true');
      return { featured };
    },
  },
  {
    path: '/products',
    element: <ProductsPage />,
    loader: async () => {
      const products = await fetchProducts();
      return { products };
    },
  },
  {
    path: '/about',
    element: <AboutPage />,
  },
  {
    path: '*',
    element: <NotFoundPage />,
  },
];

// Types for type-safe navigation
export type Path = '/' | '/products' | '/about';

export type Params = Record<string, string | undefined>;

